// 데모 모드 전용 로그인 API

export const LoginAPI = {
  login: async ({ loginId, password }) => {
    // axios_api.post("/user/login", {loginId, password})
    // 데모에서는 그냥 성공했다고 치고 가짜 토큰/유저정보.
    alert("데모 모드: 서버 없이 데모 계정으로 로그인되었습니다.");

    return {
      token: "DEMO_TOKEN_NO_BACKEND",
      userName: "데모사용자",
      loginId: loginId || "demoUser",
      role: "ADMIN",
    };
  },
};

export const logout = async () => {
  alert("데모 모드: 로그아웃 시뮬레이션만 합니다.");
  return { result: "LOGOUT_OK" };
};
